async def act(page):
    """
    From the current 'New Rule' page, open the Actions section, set Apply to a percent discount,
    set Discount Amount to 20, and save the rule.
    """
    # Open the Actions tab/section to reveal the Actions controls
    try:
        await page.get_by_role("link", name="Actions").click()
    except Exception:
        # Fallback to a non-exact match
        try:
            await page.get_by_role("link", name="Actions", exact=False).click()
        except Exception:
            # If we cannot click it, continue — the Actions panel might already be visible
            pass

    # Brief wait for the Actions panel to render
    await page.wait_for_timeout(500)

    # Attempt to set the Apply combobox to a percent discount option.
    # Try several candidate identifiers (label first, then known value key)
    apply_candidates = [
        {"label": "Percent of product price discount"},
        {"label": "Percent of product price"},
        {"value": "by_percent"},
    ]
    applied = False
    for candidate in apply_candidates:
        if applied:
            break
        try:
            await page.get_by_role("combobox", name="Apply").select_option(candidate)
            applied = True
            break
        except Exception:
            try:
                await page.get_by_role("combobox", name="Apply", exact=False).select_option(candidate)
                applied = True
                break
            except Exception:
                continue

    # Fill Discount Amount with 20 (try multiple likely accessible names)
    try:
        await page.get_by_role("textbox", name="Discount Amount").fill("20")
    except Exception:
        try:
            await page.get_by_role("textbox", name="Discount").fill("20")
        except Exception:
            try:
                await page.get_by_role("textbox", name="Discount Amount", exact=False).fill("20")
            except Exception:
                # If unable to find the textbox, raise so calling code sees the failure
                raise

    # Short pause to ensure UI updates
    await page.wait_for_timeout(300)

    # Save the rule (final action — may navigate away)
    try:
        await page.get_by_role("button", name="Save").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        try:
            await page.get_by_role("button", name="Save and Continue Edit").click()
            await page.wait_for_load_state("networkidle")
        except Exception:
            # Surface the error to the caller
            raise

